import ScaleOutlinedIcon from '@mui/icons-material/ScaleOutlined';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';

import { getPriceFormat } from '../../../core/utils';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { fieldSx } from '../utils/packageEditor';

interface IWeightedProductDialog {
  currencyCode?: string;
  onAdd: () => void;
  onChangeQty: (value: string) => void;
  onClose: () => void;
  open: boolean;
  price: number;
  productName: string;
  qty: string;
}

const WeightedProductDialog = ({
  currencyCode,
  onAdd,
  onChangeQty,
  onClose,
  open,
  price,
  productName,
  qty,
}: IWeightedProductDialog) => {
  const amount = Number(qty || 0) * Number(price || 0);

  return (
    <Dialog
      PaperProps={{
        sx: {
          borderRadius: '14px',
          maxWidth: 'calc(100vw - 32px)',
          overflow: 'hidden',
          width: 420,
        },
      }}
      onClose={onClose}
      open={open}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack
            alignItems="center"
            direction="row"
            spacing={1.5}
          >
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '10px',
                display: 'flex',
                flexShrink: 0,
                height: 38,
                justifyContent: 'center',
                width: 38,
              }}
            >
              <ScaleOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography
                sx={{
                  color: '#fff',
                  fontSize: '1rem',
                  fontWeight: 800,
                  lineHeight: 1.2,
                }}
              >
                Enter Kg / Litre Qty
              </Typography>
              <Typography
                sx={{
                  color: 'rgba(255,255,255,0.72)',
                  fontSize: '0.76rem',
                  mt: 0.35,
                }}
              >
                {productName}
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ background: '#F8FAFC', p: 3 }}>
        <Stack spacing={2}>
          <Box>
            <Typography
              sx={{
                color: '#142352',
                fontSize: '0.82rem',
                fontWeight: 700,
                mb: 0.75,
              }}
            >
              Qty
            </Typography>
            <TextField
              autoFocus
              fullWidth
              inputProps={{
                'aria-label': 'Kg or litre quantity',
                min: 0.01,
                step: 'any',
              }}
              onChange={(event) => onChangeQty(event.target.value)}
              placeholder="Enter Kg or litre qty"
              size="small"
              sx={fieldSx}
              type="number"
              value={qty}
            />
          </Box>

          <Box
            sx={{
              background: alpha('#2563EB', 0.05),
              border: `1px solid ${alpha('#2563EB', 0.14)}`,
              borderRadius: '12px',
              p: 1.5,
            }}
          >
            <Typography
              sx={{
                color: alpha('#142352', 0.55),
                fontSize: '0.76rem',
                fontWeight: 700,
                textTransform: 'uppercase',
              }}
            >
              Amount
            </Typography>
            <Typography
              sx={{
                color: '#142352',
                fontSize: '1rem',
                fontWeight: 800,
                mt: 0.5,
              }}
            >
              {getPriceFormat(amount, currencyCode)}
            </Typography>
          </Box>
        </Stack>
      </DialogContent>

      <DialogActions
        sx={{
          background: '#F8FAFC',
          borderTop: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
          p: 2,
        }}
      >
        <Button
          onClick={onClose}
          sx={{ fontWeight: 700, textTransform: 'none' }}
        >
          Cancel
        </Button>
        <Button
          onClick={onAdd}
          sx={{
            borderRadius: '8px',
            fontWeight: 800,
            minWidth: 124,
            textTransform: 'none',
          }}
          variant="contained"
        >
          Add Product
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(WeightedProductDialog);
