import AddShoppingCartOutlinedIcon from '@mui/icons-material/AddShoppingCartOutlined';
import Chip from '@mui/material/Chip';
import InputAdornment from '@mui/material/InputAdornment';
import SearchOutlinedIcon from '@mui/icons-material/SearchOutlined';
import {
  Box,
  CircularProgress,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';

import { IProductData } from '../../../core/Interface/product.interface';
import { getPriceFormat } from '../../../core/utils';
import { appColors } from '../../../theme/appColors';
import { fieldSx, sectionCardSx } from '../utils/packageEditor';

interface IAvailableProductsPanel {
  availableProducts: IProductData[];
  currencyCode?: string;
  handleProductCardClick: (product: IProductData) => void;
  isLoadingProducts: boolean;
  isProductError: boolean;
  searchQuery: string;
  selectedQtyMap: Record<string, number>;
  setSearchQuery: React.Dispatch<React.SetStateAction<string>>;
}

const AvailableProductsPanel = ({
  availableProducts,
  currencyCode,
  handleProductCardClick,
  isLoadingProducts,
  isProductError,
  searchQuery,
  selectedQtyMap,
  setSearchQuery,
}: IAvailableProductsPanel) => (
  <Box
    sx={{
      ...sectionCardSx,
      background: `linear-gradient(180deg, ${alpha('#DBEAFE', 0.6)} 0%, ${alpha(
        appColors.white,
        0.98
      )} 22%, ${alpha(appColors.white, 0.99)} 100%)`,
      border: `1px solid ${alpha('#60A5FA', 0.26)}`,
      boxShadow: '0 14px 34px rgba(37,99,235,0.08)',
      display: 'flex',
      flex: 1,
      flexDirection: 'column',
      height: '100%',
      minHeight: 0,
      minWidth: 0,
      overflow: 'hidden',
      width: '100%',
    }}
  >
      <Box
        sx={{
          display: 'grid',
          flex: 1,
          gap: 2,
          height: '100%',
          gridTemplateRows: 'auto minmax(0, 1fr)',
          minHeight: 0,
          p: 2.25,
        }}
      >
        <Box sx={{ minHeight: { xs: 'auto', md: 72 } }}>
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            justifyContent="space-between"
            spacing={1.5}
          >
            <Box>
              <Typography
                sx={{
                  color: '#142352',
                  fontSize: '1rem',
                  fontWeight: 800,
                }}
              >
                Add product
              </Typography>
              <Typography
                sx={{
                  color: alpha('#142352', 0.55),
                  fontSize: '0.8rem',
                  mt: 0.35,
                }}
              >
                Click any product card to add it to this package.
              </Typography>
            </Box>

            <TextField
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchOutlinedIcon
                      sx={{ color: alpha('#142352', 0.45) }}
                    />
                  </InputAdornment>
                ),
              }}
              onChange={(event) => setSearchQuery(event.target.value)}
              placeholder="Search products..."
              size="small"
              sx={{
                ...fieldSx,
                width: { xs: '100%', sm: 300 },
              }}
              value={searchQuery}
            />
          </Stack>
        </Box>

        <Box
          sx={{
            alignItems: 'stretch',
            alignContent: 'start',
            display: 'grid',
            flex: 1,
            gap: 1,
            gridAutoRows: 'minmax(136px, auto)',
            gridTemplateColumns: {
              xs: '1fr',
              md: 'repeat(2, minmax(0, 1fr))',
              xl: 'repeat(3, minmax(0, 1fr))',
            },
            height: '100%',
            minHeight: 0,
            overflowY: 'auto',
            pb: 0.25,
            pr: 0.5,
          }}
        >
          {isLoadingProducts ? (
            <Box
              sx={{
                alignItems: 'center',
                display: 'flex',
                gridColumn: '1 / -1',
                justifyContent: 'center',
                minHeight: 180,
              }}
            >
              <CircularProgress size={26} />
            </Box>
          ) : isProductError ? (
            <Box
              sx={{
                alignItems: 'center',
                background: alpha('#DC2626', 0.04),
                border: `1px dashed ${alpha('#DC2626', 0.2)}`,
                borderRadius: '12px',
                display: 'flex',
                gridColumn: '1 / -1',
                justifyContent: 'center',
                minHeight: 180,
                p: 2,
              }}
            >
              <Typography
                sx={{ color: alpha('#7F1D1D', 0.75), fontWeight: 600 }}
              >
                Unable to load products from the product list API.
              </Typography>
            </Box>
          ) : availableProducts.length > 0 ? (
            availableProducts.map((product) => {
              const selectedQty = selectedQtyMap[String(product.id)];

              return (
                <Box
                  aria-label={`Add ${product.name} to package`}
                  component="button"
                  key={product.id}
                  onClick={() => handleProductCardClick(product)}
                  sx={{
                    alignItems: 'stretch',
                    appearance: 'none',
                    background: selectedQty
                      ? `linear-gradient(180deg, ${alpha(
                          '#DBEAFE',
                          0.92
                        )} 0%, ${alpha('#EFF6FF', 0.98)} 100%)`
                      : alpha(appColors.white, 0.95),
                    border: selectedQty
                      ? '1px solid rgba(37,99,235,0.35)'
                      : '1px solid rgba(20,35,82,0.08)',
                    borderRadius: '14px',
                    boxShadow: selectedQty
                      ? '0 12px 28px rgba(37,99,235,0.10)'
                      : '0 6px 18px rgba(20,35,82,0.04)',
                    display: 'flex',
                    flexDirection: 'column',
                    font: 'inherit',
                    minHeight: 136,
                    overflow: 'hidden',
                    p: 1.15,
                    position: 'relative',
                    textAlign: 'left',
                    transition:
                      'transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease',
                    width: '100%',
                    '&:hover': {
                      border: '1px solid rgba(37,99,235,0.28)',
                      boxShadow: '0 14px 30px rgba(20,35,82,0.10)',
                      transform: 'translateY(-1px)',
                    },
                    '&:focus-visible': {
                      boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.12)}`,
                      outline: 'none',
                    },
                  }}
                >
                  <Stack
                    alignItems="flex-start"
                    direction="row"
                    justifyContent="space-between"
                    spacing={1}
                  >
                    <Box sx={{ minWidth: 0 }}>
                      <Typography
                        sx={{
                          color: alpha('#142352', 0.48),
                          fontSize: '0.62rem',
                          fontWeight: 700,
                          letterSpacing: '0.06em',
                          textTransform: 'uppercase',
                        }}
                      >
                        {product.code}
                      </Typography>
                      <Typography
                        sx={{
                          color: '#142352',
                          fontSize: '0.84rem',
                          fontWeight: 800,
                          lineHeight: 1.25,
                          mt: 0.35,
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          display: '-webkit-box',
                          WebkitBoxOrient: 'vertical',
                          WebkitLineClamp: 1,
                        }}
                      >
                        {product.name}
                      </Typography>
                    </Box>

                    <Stack
                      alignItems="flex-end"
                      spacing={0.75}
                    >
                      {product.isKgOrLitre && (
                        <Chip
                          color="info"
                          label="Kg/L"
                          size="small"
                          sx={{ fontWeight: 700 }}
                        />
                      )}
                      {selectedQty ? (
                        <Chip
                          label={`Qty ${selectedQty}`}
                          size="small"
                          sx={{
                            background: alpha('#2563EB', 0.12),
                            color: '#1D4ED8',
                            fontWeight: 700,
                          }}
                        />
                      ) : null}
                    </Stack>
                  </Stack>

                  <Typography
                    sx={{
                      color: alpha('#142352', 0.58),
                      fontSize: '0.7rem',
                      minHeight: 18,
                      mt: 0.8,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      display: '-webkit-box',
                      WebkitBoxOrient: 'vertical',
                      WebkitLineClamp: 1,
                    }}
                  >
                    {product.categoryName || 'Unsorted'}
                  </Typography>

                  <Stack
                    alignItems="center"
                    direction="row"
                    justifyContent="space-between"
                    sx={{ mt: 'auto', pt: 0.75 }}
                  >
                    <Typography
                      sx={{
                        color: '#142352',
                        fontSize: '0.82rem',
                        fontWeight: 800,
                      }}
                    >
                      {getPriceFormat(product.unitPrice, currencyCode)}
                    </Typography>

                    <Stack
                      alignItems="center"
                      direction="row"
                      spacing={0.6}
                    >
                      <AddShoppingCartOutlinedIcon
                        sx={{
                          color: selectedQty ? '#0F766E' : '#1D4ED8',
                          fontSize: 15,
                        }}
                      />
                      <Typography
                        sx={{
                          color: selectedQty ? '#0F766E' : '#1D4ED8',
                          fontSize: '0.72rem',
                          fontWeight: 700,
                        }}
                      >
                        {selectedQty
                          ? 'Added - click for more'
                          : product.isKgOrLitre
                            ? 'Click to enter qty'
                            : 'Click to add'}
                      </Typography>
                    </Stack>
                  </Stack>
                </Box>
              );
            })
          ) : (
            <Box
              sx={{
                alignItems: 'center',
                background: alpha(appColors.blueGreyishLight[80], 0.04),
                border: `1px dashed ${alpha(
                  appColors.blueGreyishLight[80],
                  0.25
                )}`,
                borderRadius: '12px',
                display: 'flex',
                gridColumn: '1 / -1',
                justifyContent: 'center',
                minHeight: 180,
                p: 2,
              }}
            >
              <Typography
                sx={{ color: alpha('#142352', 0.55), fontWeight: 600 }}
              >
                No products match the current search.
              </Typography>
            </Box>
          )}
        </Box>
      </Box>
    </Box>
);

export default React.memo(AvailableProductsPanel);
