import EditIcon from '@mui/icons-material/Edit';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import {
  Box,
  Card,
  CardContent,
  Grid,
  IconButton,
  MenuItem,
  Skeleton,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';

import { ICategory } from '../../core/Interface/category.interface';
import {
  IPackageData,
  IPackageDetailsData,
  IPackageItemData,
  IPackagePayload,
  IPackageSavePayload,
} from '../../core/Interface/package.interface';
import { IUserInfo } from '../../core/Interface/user.interface';
import { Privileges } from '../../core/types/commonType';
import { formatTimeToUtc, getPriceFormat } from '../../core/utils';
import AnimatedPage from '../../layouts/AnimatedPage';
import { appColors, HEADER_GRADIENT } from '../../theme/appColors';
import EditPackageModel from './components/EditPackageModel';
import {
  useGetAllPackageQuery,
  useGetCategoryQuery,
  useGetUserQuery,
} from '../posApi';

const defaultPackageQuery: IPackagePayload = {
  pageIndex: 0,
  pageSize: 500,
  searchText: '',
};

const defaultCategoryQuery = {
  pageIndex: 0,
  pageSize: 5000,
  searchText: '',
};

const searchFieldSx = {
  width: { sm: '100%', md: 280 },
  '& .MuiOutlinedInput-input': {
    color: '#fff',
    fontSize: 13,
    '&::placeholder': {
      color: 'rgba(255,255,255,0.55)',
      opacity: 1,
    },
  },
  '& .MuiOutlinedInput-root': {
    backdropFilter: 'blur(8px)',
    backgroundColor: 'rgba(255,255,255,0.12)',
    borderRadius: '8px',
    height: 40,
    '& fieldset': { borderColor: 'rgba(255,255,255,0.22)' },
    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.45)' },
    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.7)' },
  },
};

const categoryFieldSx = {
  width: { sm: '100%', md: 220 },
  '& .MuiInputBase-input': {
    color: '#fff',
    fontSize: 13,
  },
  '& .MuiOutlinedInput-root': {
    backdropFilter: 'blur(8px)',
    backgroundColor: 'rgba(255,255,255,0.12)',
    borderRadius: '8px',
    height: 40,
    '& fieldset': { borderColor: 'rgba(255,255,255,0.22)' },
    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.45)' },
    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.7)' },
  },
  '& .MuiSelect-icon': { color: 'rgba(255,255,255,0.8)' },
};

const isPackageActive = (item: IPackageData) =>
  item.isActive === true || item.isActive === 1 || item.isEnabled === true;

const isPackageDeleted = (item: IPackageData) =>
  item.isDeleted === true || item.isDeleted === 1;

const getCategoryKey = (item: IPackageData) =>
  item.categoryId || item.categoryCode || item.categoryName || 'UNCATEGORIZED';

const getCategoryLabel = (
  item: IPackageData,
  categoryMap: Record<string, string>
) =>
  item.categoryName ||
  (item.categoryId ? categoryMap[item.categoryId] : '') ||
  item.categoryCode ||
  item.categoryId ||
  'Unsorted';

const getPackagePrice = (item: IPackageData) =>
  typeof item.price === 'number' ? item.price : Number(item.unitPrice ?? 0);

const normalizePackageRecords = (value: unknown): IPackageData[] => {
  if (Array.isArray(value)) {
    return value as IPackageData[];
  }

  if (!value || typeof value !== 'object') {
    return [];
  }

  const data = value as { records?: unknown };
  return Array.isArray(data.records) ? (data.records as IPackageData[]) : [];
};

const renderPackageSkeleton = () => (
  <Box
    sx={{
      display: 'grid',
      gap: 2,
      gridTemplateColumns: {
        xs: '1fr',
        md: 'repeat(2, minmax(0, 1fr))',
        xl: 'repeat(3, minmax(0, 1fr))',
      },
    }}
  >
    {[0, 1, 2].map((item) => (
      <Card
        key={item}
        sx={{
          border: '1px solid rgba(20,35,82,0.08)',
          borderRadius: '12px',
          boxShadow: 'none',
        }}
      >
        <Skeleton
          height={140}
          variant="rectangular"
        />
        <CardContent sx={{ p: 2 }}>
          <Skeleton width="35%" />
          <Skeleton
            height={28}
            width="70%"
          />
          <Skeleton width="45%" />
          <Skeleton
            sx={{ mt: 1 }}
            width="55%"
          />
          <Skeleton width="90%" />
        </CardContent>
      </Card>
    ))}
  </Box>
);

const Package = () => {
  const [searchQuery, setSearchQuery] = React.useState('');
  const [selectedCategory, setSelectedCategory] = React.useState('All');
  const [openEditPackage, setOpenEditPackage] = React.useState(false);
  const [selectedPackageId, setSelectedPackageId] = React.useState<
    string | undefined
  >(undefined);
  const [packageItemsById, setPackageItemsById] = React.useState<
    Record<string, IPackageItemData[]>
  >({});
  const deferredSearchQuery = React.useDeferredValue(searchQuery);

  const {
    data: packageResponse,
    isError,
    isLoading,
  } = useGetAllPackageQuery(defaultPackageQuery);
  const { data: categoryResponse } = useGetCategoryQuery(defaultCategoryQuery);
  const { data: userResponse } = useGetUserQuery();

  const userInfo = userResponse?.data as IUserInfo | undefined;
  const currencyCode = userInfo?.company?.currencyCode;
  const canEdit =
    userInfo?.privileges?.includes(Privileges.ProductEdit) ?? false;
  const categoryList = React.useMemo(
    () => (categoryResponse?.data as ICategory[] | undefined) ?? [],
    [categoryResponse?.data]
  );
  const categoryMap = React.useMemo(
    () =>
      categoryList.reduce<Record<string, string>>((acc, category) => {
        acc[category.id] = category.name;
        return acc;
      }, {}),
    [categoryList]
  );

  const packages = React.useMemo(
    () =>
      normalizePackageRecords(packageResponse?.data).filter(
        (item) => item && !isPackageDeleted(item)
      ),
    [packageResponse?.data]
  );

  const categoryOptions = React.useMemo(() => {
    const categoriesByCode = new Map<string, string>();

    packages.forEach((item) => {
      categoriesByCode.set(
        getCategoryKey(item),
        getCategoryLabel(item, categoryMap)
      );
    });

    return Array.from(categoriesByCode.entries())
      .map(([code, name]) => ({ code, name }))
      .sort((left, right) => left.name.localeCompare(right.name));
  }, [categoryMap, packages]);

  React.useEffect(() => {
    if (selectedCategory === 'All') {
      return;
    }

    if (
      !categoryOptions.some(
        (category) => category.code === selectedCategory
      )
    ) {
      setSelectedCategory('All');
    }
  }, [categoryOptions, selectedCategory]);

  const normalizedQuery = deferredSearchQuery.trim().toLowerCase();

  const searchablePackages = React.useMemo(() => {
    if (!normalizedQuery) {
      return packages;
    }

    return packages.filter((item) => {
      const searchableText = [
        item.name,
        item.code,
        getCategoryLabel(item, categoryMap),
        item.description1 ?? '',
        item.description2 ?? '',
        item.description3 ?? '',
        item.description4 ?? '',
        item.description5 ?? '',
      ]
        .join(' ')
        .toLowerCase();

      return searchableText.includes(normalizedQuery);
    });
  }, [categoryMap, normalizedQuery, packages]);

  const visiblePackages = React.useMemo(() => {
    const scopedPackages =
      selectedCategory === 'All'
        ? searchablePackages
        : searchablePackages.filter(
            (item) => getCategoryKey(item) === selectedCategory
          );

    return [...scopedPackages].sort((left, right) => {
      if (isPackageActive(left) !== isPackageActive(right)) {
        return Number(isPackageActive(right)) - Number(isPackageActive(left));
      }

      return left.name.localeCompare(right.name);
    });
  }, [searchablePackages, selectedCategory]);

  const emptyMessage =
    packages.length === 0
      ? 'No package data is available from the package endpoint.'
      : 'No packages match the current search or category filter.';

  const handleEditPackage = React.useCallback(
    (item: IPackageData) => {
      setSelectedPackageId(String(item.id));
      setOpenEditPackage(true);
    },
    []
  );

  const syncPackageItems = React.useCallback(
    (packageData: IPackageDetailsData | IPackageSavePayload) => {
      setPackageItemsById((currentState) => ({
        ...currentState,
        [packageData.packageId]: packageData.items,
      }));
    },
    []
  );

  if (isError) {
    return (
      <AnimatedPage>
        <Box
          data-testid="package-container"
          sx={{
            alignItems: 'center',
            border: `1px dashed ${alpha(appColors.blueGreyishLight[80], 0.3)}`,
            borderRadius: '12px',
            display: 'flex',
            justifyContent: 'center',
            minHeight: 'calc(100vh - 220px)',
            p: 4,
          }}
        >
          <Typography sx={{ color: alpha('#142352', 0.72), fontWeight: 600 }}>
            {packageResponse?.message || 'Unable to load package data.'}
          </Typography>
        </Box>
      </AnimatedPage>
    );
  }

  return (
    <AnimatedPage>
      <Box data-testid="package-container">
        <Box
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: 2,
            color: '#fff',
            mb: 3,
            overflow: 'hidden',
            position: 'relative',
            px: { xs: 2, md: 3 },
            py: { xs: 1.5, md: 2 },
          }}
        >
          <Box
            sx={{
              background: 'rgba(255,255,255,0.07)',
              borderRadius: '50%',
              height: 220,
              inset: 'auto -60px -100px auto',
              pointerEvents: 'none',
              position: 'absolute',
              width: 220,
            }}
          />
          <Box
            sx={{
              background: 'rgba(255,255,255,0.05)',
              borderRadius: '50%',
              height: 260,
              inset: '-100px auto auto 55%',
              pointerEvents: 'none',
              position: 'absolute',
              width: 260,
            }}
          />

          <Box
            sx={{
              alignItems: { xs: 'flex-start', sm: 'center' },
              display: 'flex',
              flexDirection: { xs: 'column', sm: 'row' },
              gap: '20px',
              justifyContent: 'space-between',
              position: 'relative',
            }}
          >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  backdropFilter: 'blur(8px)',
                  background: 'rgba(255,255,255,0.14)',
                  border: '1px solid rgba(255,255,255,0.18)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 44,
                  justifyContent: 'center',
                  width: 44,
                }}
              >
                <Inventory2OutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography
                  sx={{
                    color: '#fff',
                    fontSize: { xs: '1rem', md: '1.2rem' },
                    fontWeight: 800,
                    letterSpacing: '-0.02em',
                    lineHeight: 1.2,
                  }}
                >
                  Package
                </Typography>
                <Typography
                  sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }}
                >
                  {visiblePackages.length} of {packages.length} packages
                </Typography>
              </Box>
            </Box>

            <Box
              sx={{
                display: 'flex',
                flexDirection: { xs: 'column', sm: 'row' },
                gap: 1,
                width: { xs: '100%', sm: 'auto' },
              }}
            >
              <TextField
                inputProps={{ 'aria-label': 'Category' }}
                onChange={(event) => setSelectedCategory(event.target.value)}
                select
                size="small"
                sx={categoryFieldSx}
                value={selectedCategory}
              >
                <MenuItem value="All">All Categories</MenuItem>
                {categoryOptions.map((category) => (
                  <MenuItem
                    key={category.code}
                    value={category.code}
                  >
                    {category.name}
                  </MenuItem>
                ))}
              </TextField>

              <TextField
                autoComplete="off"
                onChange={(event) => setSearchQuery(event.target.value)}
                placeholder="Search by name, code or category..."
                size="small"
                sx={searchFieldSx}
                value={searchQuery}
              />
            </Box>
          </Box>
        </Box>

        {isLoading ? (
          renderPackageSkeleton()
        ) : visiblePackages.length > 0 ? (
          <Grid
            container
            spacing={1}
          >
            {visiblePackages.map((item) => {
              const categoryName = getCategoryLabel(item, categoryMap);
              const packageKey = String(item.id);
              const loadedPackageItems = packageItemsById[packageKey];
              const loadedItemCount = loadedPackageItems?.length ?? 0;
              const hasLoadedPackageItems = packageKey in packageItemsById;
              const descriptions = [
                item.description1,
                item.description2,
                item.description3,
                item.description4,
                item.description5,
              ].filter(Boolean) as string[];
              const packageSummaryText = hasLoadedPackageItems
                ? loadedItemCount > 0
                  ? (loadedPackageItems ?? [])
                      .map((product) => product.productName)
                      .join(' | ')
                  : 'No products added to this package yet.'
                : descriptions.length > 0
                  ? descriptions.join(' | ')
                  : item.updatedDate || item.createdDate
                    ? `Created ${formatTimeToUtc(
                        item.updatedDate || item.createdDate || ''
                      )}`
                    : 'No package description is available.';

              return (
                <Grid
                  item
                  key={item.id}
                  
                >
                  <Card
                    sx={{
                      background: '#F8FAFC',
                      border: '1px solid rgba(20,35,82,0.08)',
                      borderRadius: '12px',
                      boxShadow: '0 1px 4px rgba(20,35,82,0.06)',
                      display: 'flex',
                      flex: 1,
                      flexDirection: 'column',
                      minHeight: 280,
                      overflow: 'hidden',
                    }}
                    variant="outlined"
                  >
                  <Box
                    sx={{
                      alignItems: 'flex-start',
                      background: alpha('#E0EAFF', 0.7),
                      borderBottom: '1px solid rgba(20,35,82,0.08)',
                      color: '#142352',
                      minHeight: 112,
                      p: 2,
                    }}
                  >
                    <Box sx={{ minWidth: 0 }}>
                      <Typography
                        sx={{
                          color: alpha('#142352', 0.56),
                          fontSize: '0.72rem',
                          fontWeight: 700,
                          letterSpacing: '0.08em',
                          textTransform: 'uppercase',
                        }}
                      >
                        {item.code}
                      </Typography>
                      <Typography
                        sx={{
                          fontSize: '1.05rem',
                          fontWeight: 800,
                          lineHeight: 1.25,
                          mt: 0.75,
                        }}
                      >
                        {item.name}
                      </Typography>
                    </Box>
                  </Box>

                    <CardContent
                      sx={{
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'column',
                        gap: 1.5,
                        p: 2,
                      }}
                    >
                      <Box>
                        <Box
                          sx={{
                            display: 'grid',
                            gap: 1.25,
                            gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
                          }}
                        >
                          <Box>
                            <Typography
                              sx={{
                                color: alpha('#142352', 0.45),
                                fontSize: '0.68rem',
                                fontWeight: 700,
                                letterSpacing: '0.06em',
                                textTransform: 'uppercase',
                              }}
                            >
                              Category
                            </Typography>
                            <Typography
                              sx={{
                                color: '#142352',
                                fontSize: '0.92rem',
                                fontWeight: 700,
                                mt: 0.35,
                              }}
                            >
                              {categoryName}
                            </Typography>
                          </Box>

                          <Box>
                            <Typography
                              sx={{
                                color: alpha('#142352', 0.45),
                                fontSize: '0.68rem',
                                fontWeight: 700,
                                letterSpacing: '0.06em',
                                textTransform: 'uppercase',
                              }}
                            >
                              Status
                            </Typography>
                            <Typography
                              sx={{
                                color: '#142352',
                                fontSize: '0.92rem',
                                fontWeight: 700,
                                mt: 0.35,
                              }}
                            >
                              {isPackageActive(item) ? 'Enabled' : 'Disabled'}
                            </Typography>
                          </Box>
                        </Box>
                      </Box>

                      <Box>
                        <Box
                          sx={{
                            alignItems: 'flex-end',
                            display: 'flex',
                            justifyContent: 'space-between',
                          }}
                        >
                          <Box>
                            <Typography
                              sx={{
                                color: alpha('#142352', 0.45),
                                fontSize: '0.68rem',
                                fontWeight: 700,
                                letterSpacing: '0.06em',
                                textTransform: 'uppercase',
                              }}
                            >
                              Price
                            </Typography>
                            <Typography
                              sx={{
                                color: '#142352',
                                fontSize: '1rem',
                                fontWeight: 800,
                                mt: 0.35,
                              }}
                            >
                              {getPriceFormat(
                                getPackagePrice(item),
                                currencyCode
                              )}
                            </Typography>
                          </Box>

                          {hasLoadedPackageItems ? (
                            <Typography
                              sx={{
                                color: alpha('#142352', 0.45),
                                fontSize: '0.78rem',
                                fontWeight: 600,
                              }}
                            >
                              {`${loadedItemCount} products added`}
                            </Typography>
                          ) : null}
                        </Box>
                      </Box>

                      <Box>
                        <Box
                          sx={{
                            background: alpha(
                              appColors.blueGreyishLight[80],
                              0.04
                            ),
                            border: `1px solid ${alpha(
                              appColors.blueGreyishLight[80],
                              0.16
                            )}`,
                            borderRadius: '10px',
                            mt: 'auto',
                            p: 1.5,
                          }}
                        >
                          <Typography
                            sx={{
                              color: alpha('#142352', 0.45),
                              fontSize: '0.68rem',
                              fontWeight: 700,
                              letterSpacing: '0.06em',
                              mb: 0.75,
                              textTransform: 'uppercase',
                            }}
                          >
                            Details
                          </Typography>
                          <Typography
                            sx={{
                              color: alpha('#142352', 0.76),
                              display: '-webkit-box',
                              fontSize: '0.88rem',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              WebkitBoxOrient: 'vertical',
                              WebkitLineClamp: 3,
                            }}
                          >
                            {packageSummaryText}
                          </Typography>
                        </Box>
                      </Box>

                      {canEdit && (
                        <Box
                          sx={{
                            display: 'flex',
                            justifyContent: 'flex-end',
                          }}
                        >
                          <IconButton
                            aria-label="Edit"
                            onClick={() => handleEditPackage(item)}
                            size="small"
                            sx={{
                              color: '#2563EB',
                              p: 0.25,
                              '&:hover': {
                                background: alpha('#2563EB', 0.08),
                                color: '#1D4ED8',
                              },
                            }}
                          >
                            <EditIcon sx={{ fontSize: 18 }} />
                          </IconButton>
                        </Box>
                      )}
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>
        ) : (
          <Box
            sx={{
              alignItems: 'center',
              background: alpha(appColors.blueGreyishLight[80], 0.04),
              border: `1px dashed ${alpha(
                appColors.blueGreyishLight[80],
                0.25
              )}`,
              borderRadius: '8px',
              display: 'flex',
              flexDirection: 'column',
              gap: 1,
              justifyContent: 'center',
              minHeight: 'calc(100vh - 380px)',
              px: 2,
              py: 6,
            }}
          >
            <Inventory2OutlinedIcon
              sx={{ color: alpha('#142352', 0.2), fontSize: 40 }}
            />
            <Typography sx={{ color: alpha('#142352', 0.5), fontWeight: 700 }}>
              No packages found
            </Typography>
            <Typography
              sx={{
                color: alpha('#142352', 0.45),
                fontSize: '0.9rem',
                maxWidth: 420,
                textAlign: 'center',
              }}
            >
              {emptyMessage}
            </Typography>
          </Box>
        )}

        {openEditPackage && selectedPackageId && (
          <EditPackageModel
            currencyCode={currencyCode}
            handleCloseDialog={() => {
              setOpenEditPackage(false);
              setSelectedPackageId(undefined);
            }}
            onPackageLoaded={syncPackageItems}
            onPackageSaved={syncPackageItems}
            open={openEditPackage}
            packageId={selectedPackageId}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default Package;
