import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import {
  Box,
  Chip,
  IconButton,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';

import { IPackageItemData } from '../../../core/Interface/package.interface';
import { IProductData } from '../../../core/Interface/product.interface';
import { getPriceFormat } from '../../../core/utils';
import { appColors } from '../../../theme/appColors';
import { fieldSx, sectionCardSx } from '../utils/packageEditor';

interface ISelectedProductsPanel {
  currencyCode?: string;
  handleQtyChange: (
    productId: string,
    nextQty: string,
    isKgOrLitre?: boolean
  ) => void;
  handleRemoveProduct: (productId: string) => void;
  productMap: Record<string, IProductData>;
  selectedItems: IPackageItemData[];
}

const SelectedProductsPanel = ({
  currencyCode,
  handleQtyChange,
  handleRemoveProduct,
  productMap,
  selectedItems,
}: ISelectedProductsPanel) => {
  const totalAmount = React.useMemo(
    () =>
      selectedItems.reduce(
        (summary, item) => {
          const unitPrice = productMap[item.productId]?.unitPrice ??
            item.unitPrice ??
            0;

          return summary + unitPrice * Number(item.qty || 0);
        },
        0
      ),
    [productMap, selectedItems]
  );

  return (
    <Box
      sx={{
        ...sectionCardSx,
        background: `linear-gradient(180deg, ${alpha('#D1FAE5', 0.72)} 0%, ${alpha(
          appColors.white,
          0.98
        )} 22%, ${alpha(appColors.white, 0.99)} 100%)`,
        border: `1px solid ${alpha('#34D399', 0.28)}`,
        boxShadow: '0 14px 34px rgba(15,118,110,0.08)',
        display: 'flex',
        flex: 1,
        flexDirection: 'column',
        height: '100%',
        minHeight: 0,
        minWidth: 0,
        overflow: 'hidden',
        width: '100%',
      }}
    >
      <Box
        sx={{
          display: 'grid',
          flex: 1,
          gap: 1.5,
          height: '100%',
          gridTemplateRows: 'auto minmax(0, 1fr)',
          minHeight: 0,
          p: 2.25,
        }}
      >
        <Box sx={{ minHeight: { xs: 'auto', md: 72 } }}>
          <Stack
            alignItems={{ xs: 'flex-start', sm: 'center' }}
            direction={{ xs: 'column', sm: 'row' }}
            justifyContent="space-between"
            spacing={1}
          >
            <Box>
              <Typography
                sx={{
                  color: '#123B33',
                  fontSize: '1rem',
                  fontWeight: 800,
                }}
              >
                Added products ({selectedItems.length})
              </Typography>
              <Typography
                sx={{
                  color: alpha('#123B33', 0.62),
                  fontSize: '0.8rem',
                  mt: 0.35,
                }}
              >
                Edit qty here or remove products before saving the package.
              </Typography>
            </Box>

            <Box
              sx={{
                alignSelf: { xs: 'stretch', sm: 'center' },
                background: alpha('#10B981', 0.08),
                border: `1px solid ${alpha('#10B981', 0.16)}`,
                borderRadius: '12px',
                minWidth: { xs: '100%', sm: 220 },
                px: 1.4,
                py: 0.9,
              }}
            >
              <Typography
                sx={{
                  color: alpha('#123B33', 0.65),
                  fontSize: '0.68rem',
                  fontWeight: 700,
                  letterSpacing: '0.04em',
                  textTransform: 'uppercase',
                }}
              >
                Calculated total
              </Typography>
              <Typography
                sx={{
                  color: '#047857',
                  fontWeight: 800,
                  mt: 0.2,
                }}
              >
                {getPriceFormat(totalAmount, currencyCode)}
              </Typography>
            </Box>
          </Stack>
        </Box>

        <Box
          sx={{
            display: 'flex',
            flex: 1,
            flexDirection: 'column',
            gap: 0.7,
            height: '100%',
            minHeight: 0,
            overflowY: 'auto',
            pb: 0.25,
            pr: 0.5,
          }}
        >
          {selectedItems.length > 0 ? (
            selectedItems.map((item) => {
              const matchedProduct = productMap[item.productId];
              const isKgOrLitre =
                matchedProduct?.isKgOrLitre || item.isKgOrLitre;
              const unitPrice =
                matchedProduct?.unitPrice ?? item.unitPrice ?? 0;
              const lineTotal = unitPrice * Number(item.qty || 0);

              return (
                <Box
                  key={item.productId}
                  sx={{
                    background: alpha(appColors.white, 0.96),
                    border: '1px solid rgba(20,35,82,0.12)',
                    p: 0.85,
                  }}
                >
                  <Stack
                    alignItems={{ xs: 'stretch', sm: 'center' }}
                    direction={{ xs: 'column', sm: 'row' }}
                    justifyContent="space-between"
                    spacing={0.9}
                  >
                    <Stack
                      alignItems={{ xs: 'flex-start', sm: 'center' }}
                      direction="row"
                      spacing={0.9}
                      sx={{ flex: 1, minWidth: 0 }}
                    >
                      <Box sx={{ flex: 1, minWidth: 0 }}>
                        <Typography
                          sx={{
                            color: alpha('#123B33', 0.52),
                            fontSize: '0.58rem',
                            fontWeight: 700,
                            letterSpacing: '0.06em',
                            textTransform: 'uppercase',
                          }}
                        >
                          {item.productCode}
                        </Typography>
                        <Typography
                          sx={{
                            color: '#123B33',
                            fontSize: '0.8rem',
                            fontWeight: 800,
                            lineHeight: 1.25,
                            mt: 0.18,
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {item.productName}
                        </Typography>
                      </Box>

                    <Stack
                      direction="row"
                      spacing={0.65}
                    >
                      {isKgOrLitre && (
                        <Chip
                          color="info"
                          label="Kg/L"
                          size="small"
                          sx={{
                            fontWeight: 700,
                            height: 21,
                          }}
                        />
                      )}
                    </Stack>
                    </Stack>

                    <Stack
                      alignItems="center"
                      direction="row"
                      spacing={0.65}
                      sx={{ flexShrink: 0 }}
                    >
                      <Box
                        sx={{
                          background: alpha('#10B981', 0.08),
                          borderRadius: '999px',
                          color: '#047857',
                          fontSize: '0.68rem',
                          fontWeight: 800,
                          px: 0.8,
                          py: 0.28,
                          whiteSpace: 'nowrap',
                        }}
                      >
                        {getPriceFormat(lineTotal, currencyCode)}
                      </Box>
                      <TextField
                        aria-label={`${item.productName} qty`}
                        inputProps={{
                          min: isKgOrLitre ? 0.01 : 1,
                          step: isKgOrLitre ? 'any' : 1,
                        }}
                        onChange={(event) =>
                          handleQtyChange(
                            item.productId,
                            event.target.value,
                            isKgOrLitre
                          )
                        }
                        size="small"
                        sx={{
                          ...fieldSx,
                          width: 76,
                          '& .MuiOutlinedInput-input': {
                            fontSize: '0.76rem',
                            fontWeight: 700,
                            py: 0.7,
                          },
                        }}
                        type="number"
                        value={item.qty}
                      />
                      <IconButton
                        aria-label={`Remove ${item.productName}`}
                        onClick={() => handleRemoveProduct(item.productId)}
                        sx={{
                          background: alpha('#FEE2E2', 0.52),
                          border: '1px solid rgba(220,38,38,0.15)',
                          borderRadius: '8px',
                          color: '#DC2626',
                          p: 0.55,
                        }}
                      >
                        <DeleteOutlineIcon sx={{ fontSize: 15 }} />
                      </IconButton>
                    </Stack>
                  </Stack>
                </Box>
              );
            })
          ) : (
            <Box
              sx={{
                alignItems: 'center',
                background: alpha('#D1FAE5', 0.35),
                border: `1px dashed ${alpha('#10B981', 0.28)}`,
                borderRadius: '12px',
                display: 'flex',
                flex: 1,
                justifyContent: 'center',
                minHeight: 180,
                p: 2,
              }}
            >
              <Typography
                sx={{ color: alpha('#123B33', 0.62), fontWeight: 600 }}
              >
                No products added to this package yet.
              </Typography>
            </Box>
          )}
        </Box>
      </Box>
    </Box>
  );
};

export default React.memo(SelectedProductsPanel);
